-- =============================================================================
-- Shipyard operations (project 3) - migrations 005..011
-- All dates are relative to current_date, so the demo stays "live" whenever the
-- seed is re-applied. Names of owners, vessels and people are fictional.
-- =============================================================================

-- Hulls and production schedule (005): ship projects entered in the app (Production tab:
-- "New hull", "Blocks", "Plan" > Draft schedule; Resources "Plan block lifts"), exported on
-- 2026-11-17. Dates are day offsets from current_date (export day = 0). Blocks have no
-- Blender geometry (the viewer draws them, HullBlockGeometry): their mesh_node_id is derived here
-- like blockMeshNodeId() in block_entities.dart, other rows reference them by hull_no + block_no.
insert into public.hulls
    (project_id, hull_no, name, ship_type, contract_type, owner_name, class_society, length_m, beam_m, deadweight_t,
     contract_date, steel_cutting_date, keel_laying_date, launching_date, contract_delivery_date, forecast_delivery_date,
     status, location_node_id)
select '33333333-3333-3333-3333-333333333333', x.hull_no, x.name, x.ship_type, x.contract_type, x.owner_name, x.class_society,
       x.length_m::numeric, x.beam_m::numeric, x.dwt::numeric,
       current_date + x.d_contract, current_date + x.d_cut, current_date + x.d_keel, current_date + x.d_launch,
       current_date + x.d_delivery, current_date + x.d_forecast, x.status, x.location
from (values
    -- hull, name, ship type, contract, owner, class, L, B, dwt, days: contract, steel cutting, keel, launching, delivery, forecast; status, location
    ('NB-1001', 'MV SeaHorse', 'Bulk Carier, 28.000 DWT', 'newbuild', null, 'DNV', 99, 13, 7, -1, 14, 45, 409, 440, 440, 'planned', null)
) as x(hull_no, name, ship_type, contract_type, owner_name, class_society, length_m, beam_m, dwt,
       d_contract, d_cut, d_keel, d_launch, d_delivery, d_forecast, status, location);

-- Hull blocks (category hull_structure, metadata as written by the Blocks dialog).
insert into public.components (project_id, mesh_node_id, name, category, material, weight_kg, status, metadata)
select '33333333-3333-3333-3333-333333333333',
       'NODE_' || regexp_replace(upper(x.hull_no), '[^A-Z0-9]', '', 'g') || '_BLOCK_'
           || regexp_replace(upper(x.block_no), '[^A-Z0-9]+', '_', 'g'),
       x.name, 'hull_structure', x.material, x.weight_kg::numeric, 'normal',
